<template><main class="container page-section home-page"><section class="intro"><p class="eyebrow">个人写作与长期积累</p><h1 class="page-title">把正在思考的事，<br>写成值得重读的内容。</h1><p class="muted">Own-Web 是一个安静的个人网站与社区博客。阅读公开文章，或在你的工作台保存学习与创作。</p><div class="cta"><RouterLink class="button button-primary" to="/explore">开始探索</RouterLink><RouterLink class="button" to="/write">写一篇文章</RouterLink></div></section><section><div class="section-heading"><div><p class="eyebrow">Latest</p><h2>最新文章</h2></div><RouterLink to="/explore?feed=latest">查看全部</RouterLink></div><div v-if="loading" class="empty" role="status">正在载入文章…</div><div v-else-if="loadError" class="empty error-state" role="alert">{{ loadError }}<button class="button button-secondary" type="button" @click="load">重试</button></div><div v-else-if="!posts.length" class="empty">还没有公开文章。成为第一个发布想法的人吧。</div><div v-else class="post-grid"><article v-for="post in posts" :key="post.id" class="card post"><img v-if="post.cover_image" class="post-cover" :src="post.cover_image" :alt="post.cover_alt_text || ''" /><div class="post-body"><p class="post-meta">{{ post.username }} · {{ date(post.published_at) }} · {{ post.reading_minutes || 1 }} 分钟</p><h3><RouterLink :to="`/posts/${post.slug}`">{{ post.title }}</RouterLink></h3><p class="muted">{{ post.excerpt || excerpt(post.content_markdown) }}</p><div class="post-stats"><span>{{ post.view_count || 0 }} 阅读</span><span>{{ post.like_count || 0 }} 喜欢</span><span>{{ post.comment_count || 0 }} 评论</span></div><div class="tags"><span v-for="category in post.categories" :key="category.slug">{{ category.name }}</span></div></div></article></div></section><section class="workbench card"><div><p class="eyebrow">Your workspace</p><h2>保留原有的学习与媒体空间</h2><p class="muted">文件分类、Markdown、站内邮件和图片、视频、音乐管理均在工作台中继续可用。</p></div><RouterLink class="button" to="/dashboard">进入工作台</RouterLink></section></main></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{RouterLink}from'vue-router';import http from'@/services/http';const posts=ref<any[]>([]),loading=ref(true),loadError=ref('');const date=(v:string|null)=>v?new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium'}).format(new Date(v)):'刚刚';const excerpt=(v:string)=>String(v||'').replace(/[#*_>`]/g,'').slice(0,110);async function load(){loading.value=true;loadError.value='';try{posts.value=(await http.get('/api/public/home')).data.latest||[]}catch(e:any){loadError.value=e.response?.data?.error?.message||'公开文章暂时无法载入，请稍后重试'}finally{loading.value=false}}onMounted(load)</script>
<style scoped>.intro{max-width:740px;padding:48px 0 72px}.intro h1{font-size:clamp(2.35rem,6vw,4.6rem);line-height:1.12;margin:12px 0 20px}.intro>p:not(.eyebrow){font-size:1.08rem;max-width:610px}.cta{display:flex;gap:12px;margin-top:28px}.section-heading{display:flex;justify-content:space-between;align-items:end;margin:0 0 18px}.section-heading h2{margin:2px 0;font-size:1.55rem}.section-heading>a{color:var(--accent);font-weight:650}.post-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.post{overflow:hidden;padding:0;min-height:280px;display:flex;flex-direction:column}.post-cover{display:block;width:100%;aspect-ratio:16/9;object-fit:cover}.post-body{display:flex;flex:1;flex-direction:column;padding:20px}.post h3{font-size:1.18rem;line-height:1.35;margin:8px 0}.post h3 a{text-decoration:none}.post h3 a:hover{color:var(--accent)}.post-meta{font-size:.8rem;color:var(--subtle);margin:0}.post-stats{display:flex;flex-wrap:wrap;gap:var(--space-2);margin-top:auto;padding-top:var(--space-3);color:var(--subtle);font-size:.78rem}.tags{display:flex;gap:6px;flex-wrap:wrap;margin-top:10px}.tags span{font-size:.78rem;color:var(--accent);background:var(--accent-soft);padding:3px 7px;border-radius:20px}.workbench{margin-top:56px;padding:24px;display:flex;gap:24px;align-items:center;justify-content:space-between}.workbench h2{margin:4px 0}.workbench p{margin-bottom:0}.empty{display:grid;justify-items:center;gap:var(--space-2);padding:var(--space-6);color:var(--muted)}.error-state{border:1px solid var(--border);border-radius:var(--radius)}@media(max-width:900px){.post-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:760px){.post-grid{grid-template-columns:1fr}.workbench{align-items:start;flex-direction:column}.intro{padding-top:28px}}
</style>
